const PAYLOAD = [{"id":"pnj-grands-exiles-alby-vandal-29","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Alby Vandal","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Croix d’Emphyrra","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Alby Vandal","real_name_source":"Alby Vandal","nom_verite":"Albirith Vadel","nom_verite_source":"Albirith Vadel","race":"Elfe","age":"25 ans","origine":"Américaine","statut":"","affiliations":"Corporation : biosun","source_group":"Croix d’Emphyrra","source_groups":["Croix d’Emphyrra"],"source_pages":[23],"source_occurrences":1,"source_order":1,"identity_keys":["Alby Vandal","Albirith Vadel","Hibou d’onyx : Albirith"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Hibou d’onyx : Albirith Nom de la Réalité : Alby Vandal Nom de la Vérité : Albirith Vadel Age : «25ans », ???? Affiliations : Corporation : biosun Nationalité d’origine : Américaine Ethnie réelle : Elfe Sous-faction : Chef des Hiboux d’onyx Alby Vandal est médecin et chercheuse pour Biosun corporation. Elle ne joue pas un rôle de haut cadre mais c’est un membre actif de terrain. Elle est souvent mandatée pour traiter avec les fixers et les crawlers au besoin. Les Hiboux d’onyx ont élu à leur tête la dénommée Albirith, qui se trouve être la fille de Mirissi, la précédente reine de la Chasse. Albirith est aussi la fille d’Obéron et a été élevée par Titania en grande partie. Elle a été membre de la Chasse pendant de longs siècles, avant de trouver Titania trop inactive et de la défier pour récupérer la tête de la Chasse en 1855. Elle n’a jamais connu une défaite aussi totale et a été bannie de la Chasse, non sans que Titania n’en soit mécontente : bien qu’ayant écrasé sa disciple sans pitié, ellea perdu un Grand Veneur compétent de confiance et un successeur probable, même si la « jeune » a tenté sa chance un demi-millénaire trop tôt. Frustrée et sadique de nature, Albirith tient de ses parents des talents tactiques et martiaux, ironiquement, elle est désormais ennemie de ses trois parents en quelque sorte, au moins politiquement."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Alby Vandal"],["Âge apparent","25 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Alby Vandal est médecin et chercheuse pour Biosun corporation. Elle ne joue pas un rôle de haut cadre mais c’est un membre actif de terrain. Elle est souvent mandatée pour traiter avec les fixers et les crawlers au besoin."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Hibou d’onyx : Albirith"],["Nom de la Réalité","Alby Vandal"],["Nom de la Vérité","Albirith Vadel"],["Âge complet","25 ans en apparence ; âge réel inconnu"],["Affiliations","Corporation : biosun"],["Nationalité d’origine","Américaine"],["Nature réelle","Elfe"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Les Hiboux d’onyx ont élu à leur tête la dénommée Albirith, qui se trouve être la fille de Mirissi, la précédente reine de la Chasse. Albirith est aussi la fille d’Obéron et a été élevée par Titania en grande partie. Elle a été membre de la Chasse pendant de longs siècles, avant de trouver Titania trop inactive et de la défier pour récupérer la tête de la Chasse en 1855. Elle n’a jamais connu une défaite aussi totale et a été bannie de la Chasse, non sans que Titania n’en soit mécontente : bien qu’ayant écrasé sa disciple sans pitié, ellea perdu un Grand Veneur compétent de confiance et un successeur probable, même si la « jeune » a tenté sa chance un demi-millénaire trop tôt. Frustrée et sadique de nature, Albirith tient de ses parents des talents tactiques et martiaux, ironiquement, elle est désormais ennemie de ses trois parents en quelque sorte, au moins politiquement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-leonard-rufendov-30","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Leonard Rufendov","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Croix d’Emphyrra","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Leonard Rufendov","real_name_source":"Leonard Rufendov","nom_verite":"Lyndereth","nom_verite_source":"Lyndereth","race":"Elfe","age":"37 ans","origine":"Russe","statut":"","affiliations":"Crawlers : gundriver","source_group":"Croix d’Emphyrra","source_groups":["Croix d’Emphyrra"],"source_pages":[23],"source_occurrences":1,"source_order":2,"identity_keys":["Leonard Rufendov","Lyndereth","Hibou d’onyx : Lyndereth"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Hibou d’onyx : Lyndereth Nom de la Réalité : Leonard Rufendov Nom de la Vérité : Lyndereth Age : «37 ans » - ???? ans Affiliations : Crawlers : gundriver Nationalité d’origine : Russe Ethnie réelle : Elfe Sous-faction : Sous-Chef des Hiboux d’onyx Leonard Staff est un gundriver, c’est-à-dire un « transporteur » chez les crawler. Compétent en pilotage de presque tous les véhicules, il a un module roulant pouvant déployer quatre rotors afin de décoller en cas d’urgence. Il aurait fait la guerre de 22-28 mais refuse d’en parler, la rumeur dit qu’il serait un Russe asservi par les Nord-Coréens et aurait combattu pour eux. Comme Albirith, Lyndereth est un ancien de la Chasse Fantastique, Veneur réputé, il en a eu assez de traquer des descendants d’elfes noirs, après la tentative d’Albirith pour prendre la tête, il l’a suivi. A eux deux, ils ont repris la sous-faction du « Hibou », très liées aux deimons et aux gorgones jusque-là, au point d’être dirigée par Shagma, un deimon qui avait la forme d’un elfe. Les réelles ambitions de Lyndereth sont de trouver et tuer Mirissi et Nerediath Lisindrith et d’utiliser cela pour rallier les membres de la « confrérie de la faux » qui ne sont pas encore corrompus. Son arme est un pistolet singulier puisqu’il s’agit d’une gorgone sans corps possédant l’arme."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Leonard Rufendov"],["Âge apparent","37 ans"],["Nationalité déclarée","Russe"]]},{"type":"p","text":"Leonard Staff est un gundriver, c’est-à-dire un « transporteur » chez les crawler. Compétent en pilotage de presque tous les véhicules, il a un module roulant pouvant déployer quatre rotors afin de décoller en cas d’urgence. Il aurait fait la guerre de 22-28 mais refuse d’en parler, la rumeur dit qu’il serait un Russe asservi par les Nord-Coréens et aurait combattu pour eux."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Hibou d’onyx : Lyndereth"],["Nom de la Réalité","Leonard Rufendov"],["Nom de la Vérité","Lyndereth"],["Âge complet","37 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : gundriver"],["Nationalité d’origine","Russe"],["Nature réelle","Elfe"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Comme Albirith, Lyndereth est un ancien de la Chasse Fantastique, Veneur réputé, il en a eu assez de traquer des descendants d’elfes noirs, après la tentative d’Albirith pour prendre la tête, il l’a suivi. A eux deux, ils ont repris la sous-faction du « Hibou », très liées aux deimons et aux gorgones jusque-là, au point d’être dirigée par Shagma, un deimon qui avait la forme d’un elfe. Les réelles ambitions de Lyndereth sont de trouver et tuer Mirissi et Nerediath Lisindrith et d’utiliser cela pour rallier les membres de la « confrérie de la faux » qui ne sont pas encore corrompus. Son arme est un pistolet singulier puisqu’il s’agit d’une gorgone sans corps possédant l’arme."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-gerald-ashorn-31","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gerald Ashorn","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Gerald Ashorn","real_name_source":"Gerald Ashorn","nom_verite":"Ashorn","nom_verite_source":"Ashorn","race":"Orques (thulkar)","age":"50 ans","origine":"Américaine","statut":"","affiliations":"Sportif","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[26],"source_occurrences":1,"source_order":1,"identity_keys":["Gerald Ashorn","Ashorn","Horde divine : Ashorn"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde divine : Ashorn Nom de la Réalité : Gerald Ashorn Nom de la Vérité : Ashorn Age : « 50ans « - ?? ans Affiliations : Sportif Nationalité d’origine : Américaine Ethnie réelle : Orques (thulkar) Titre de la horde : Maitre de horde / « Fils de la guerre » Gerald Ashon était le plus charismatique et devint le plus influent des généraux pendant la guerre, à la mort des plus connus qui furent tués au Japon pendant la tentative de reconquête ou durant des assauts Coréens, exécutés pour haute trahison pour ceux tentant de fuir la débâcle totale des premiers mois. Commandant les forces de l’US. Marines corp, on lui doit la protection renforcée du PCRC ou bien encore le fait qu’il ne laisse Siobhain combattre comme les autres. Lui-même a été en première ligne à de nombreuses batailles. A Daegu, notamment, il y est connu pour avoir fait une charge de cavalerie avec ses chars, debout sur une tourelle, contre une sphère anti-aérienne. Ashorn pourrait être considéré comme un fléau, venu d’Aèr avec sa horde après avoir percé les portes Aerethia, il attaqua les exilés comme les locaux longuement, défiant jusqu’aux dieux en duel. Etrangement, il est en bon termes avec Morrighan peut être parce qu’il incarne presque tous ses attributs avec un honneur croissant avec l’âge. Après la guerre de 22-28, il s’est plutôt reconverti dans le sport, où il détient les droits des plus grandes arènes californiennes. Il est aussi à l’origine du tournoi des maitres dans Los Demonos. Il n’existe que pour le combat même si ce n’est plus le monstre sanguinaire d’avant."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Gerald Ashorn"],["Âge apparent","50 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Gerald Ashorn fut l’un des généraux américains les plus charismatiques de la guerre de 2022-2028. Commandant des forces de l’US Marine Corps, il participa notamment à la protection renforcée du PCRC et combattit personnellement sur de nombreux fronts. Après la guerre, il s’est reconverti dans le sport, détient les droits de grandes arènes californiennes et a fondé le tournoi des maîtres de Los Demonos."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde divine : Ashorn"],["Nom de la Réalité","Gerald Ashorn"],["Nom de la Vérité","Ashorn"],["Âge complet","50 ans en apparence ; âge réel inconnu"],["Affiliations","Sportif"],["Nationalité d’origine","Américaine"],["Nature réelle","Orques (thulkar)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Gerald Ashon était le plus charismatique et devint le plus influent des généraux pendant la guerre, à la mort des plus connus qui furent tués au Japon pendant la tentative de reconquête ou durant des assauts Coréens, exécutés pour haute trahison pour ceux tentant de fuir la débâcle totale des premiers mois. Commandant les forces de l’US. Marines corp, on lui doit la protection renforcée du PCRC ou bien encore le fait qu’il ne laisse Siobhain combattre comme les autres. Lui-même a été en première ligne à de nombreuses batailles. A Daegu, notamment, il y est connu pour avoir fait une charge de cavalerie avec ses chars, debout sur une tourelle, contre une sphère anti-aérienne. Ashorn pourrait être considéré comme un fléau, venu d’Aèr avec sa horde après avoir percé les portes Aerethia, il attaqua les exilés comme les locaux longuement, défiant jusqu’aux dieux en duel. Etrangement, il est en bon termes avec Morrighan peut être parce qu’il incarne presque tous ses attributs avec un honneur croissant avec l’âge. Après la guerre de 22-28, il s’est plutôt reconverti dans le sport, où il détient les droits des plus grandes arènes californiennes. Il est aussi à l’origine du tournoi des maitres dans Los Demonos. Il n’existe que pour le combat même si ce n’est plus le monstre sanguinaire d’avant."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-kimberley-vasquez-32","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kimberley Vasquez","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kimberley Vasquez","real_name_source":"Kimberley VASQUEZ","nom_verite":"Kiarn’kay","nom_verite_source":"Kiarn’kay","race":"thulkars (orcs)","age":"42 ans","origine":"Mexicaine","statut":"","affiliations":"chasseurs fantastique","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[26],"source_occurrences":1,"source_order":2,"identity_keys":["Kimberley VASQUEZ","Kiarn’kay","Horde divine : Kiarn’kay","Kimberley Vasquez"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde divine : Kiarn’kay Nom de la Réalité : Kimberley VASQUEZ Nom de la Vérité : Kiarn’kay Age : «42 ans » - Affiliations : chasseurs fantastique Nationalité d’origine : Mexicaine Ethnie réelle : thulkars (orcs) Titre de la horde : chef en second Kimberley est la directrice de l’académie militaire MNA. Bien qu’elle soit une femme qui semble assez ouverte et tolérante, elle reste une militaire ayant fait la guerre du Mexique. L’académie dépend des corporations et du gouvernement de Californie, cependant elle n’a ni respect ni confiance envers ses financeurs, traumatisée par le conflit ayant opposé le gouvernement mexicain et les corporations. En tant qu’Orque, elle est une disciple d’Ashorn et elle est même la numéro 2 de la horde divine, le général régulier qui gère les membres de la horde, leur formation et leur sécurité. Si un membre de la communauté a un souci, elle lui en fera baver, elle le tabassera, le fera payer des années, mais lui apportera immédiatement toute l’aide qu’il désire néanmoins. L’académie est indépendante, elle utilise donc les fonds à sa guise pour soutenir les siens, mais se refuse à ce qu’elle ne soit déficitaire."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Kimberley Vasquez"],["Âge apparent","42 ans"],["Nationalité déclarée","Mexicaine"]]},{"type":"p","text":"Kimberley est la directrice de l’académie militaire MNA. Bien qu’elle soit une femme qui semble assez ouverte et tolérante, elle reste une militaire ayant fait la guerre du Mexique. L’académie dépend des corporations et du gouvernement de Californie, cependant elle n’a ni respect ni confiance envers ses financeurs, traumatisée par le conflit ayant opposé le gouvernement mexicain et les corporations."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde divine : Kiarn’kay"],["Nom de la Réalité","Kimberley Vasquez"],["Nom de la Vérité","Kiarn’kay"],["Âge complet","42 ans en apparence ; âge réel inconnu"],["Affiliations","chasseurs fantastique"],["Nationalité d’origine","Mexicaine"],["Nature réelle","thulkars (orcs)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"En tant qu’Orque, elle est une disciple d’Ashorn et elle est même la numéro 2 de la horde divine, le général régulier qui gère les membres de la horde, leur formation et leur sécurité. Si un membre de la communauté a un souci, elle lui en fera baver, elle le tabassera, le fera payer des années, mais lui apportera immédiatement toute l’aide qu’il désire néanmoins. L’académie est indépendante, elle utilise donc les fonds à sa guise pour soutenir les siens, mais se refuse à ce qu’elle soit déficitaire."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-masakoto-naisan-33","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Masakoto Naisan","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Masakoto Naisan","real_name_source":"Masakoto NAISAN","nom_verite":"Mash’Nay","nom_verite_source":"Mash’Nay","race":"orque (thulkar)","age":"39 ans","origine":"japonaise","statut":"","affiliations":"sportif","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[27],"source_occurrences":1,"source_order":1,"identity_keys":["Masakoto NAISAN","Mash’Nay","Horde divine: Mash’Nay","Masakoto Naisan"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde divine: Mash’Nay Nom de la Réalité : Masakoto NAISAN Nom de la Vérité : Mash’Nay Age : « 39 ans « - ?? ans Affiliations : sportif Nationalité d’origine : japonaise Ethnie réelle : orque (thulkar) Titre de la horde : seigneur Masakoto est une artiste martiale qu’on a ramené du Japon pour les chaines sportives en Californie. Sur un tatami, elle est encore invaincue officiellement. Officieusement, elle a été écrasée par Fuyumi et son karaté Shinoda. Elle en est devenue la disciple même si elle se refuse à l’aider pour ses affaires mafieuses. Mash est une guerrière de la horde divine, elle se drogue, boit de l’alcool et s’empoisonne régulièrement pour dégrader son corps et être « au niveau humain ». Même presque morte, elle gagne généralement tous ses combats, même si elle est souvent en difficulté tant elle s’impose de graves handicaps. Elle a une mauvaise image dans la Réalité, on la pense simplement dopée ou addict, mais sa constitution monstrueuse de Thulkar lui pose un grave souci : elle mithridatise incroyablement mieux que les humains, l’alcool n’a presque plus aucun effet par exemple. Heureusement, en 2035, des drogues plus ravageuses existent et des soins pour que ça ne soit pas définitif également. Ashorn la respecte énormément, car plutôt que s’ennuyer à son vrai haut niveau, elle se diminue sans cesse pour que le moindre adversaire même méprisable soit un défi digne d’intérêt."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Masakoto Naisan"],["Âge apparent","39 ans"],["Nationalité déclarée","japonaise"]]},{"type":"p","text":"Masakoto est une artiste martiale qu’on a ramené du Japon pour les chaines sportives en Californie. Sur un tatami, elle est encore invaincue officiellement. Officieusement, elle a été écrasée par Fuyumi et son karaté Shinoda. Elle en est devenue la disciple même si elle se refuse à l’aider pour ses affaires mafieuses."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde divine: Mash’Nay"],["Nom de la Réalité","Masakoto Naisan"],["Nom de la Vérité","Mash’Nay"],["Âge complet","39 ans en apparence ; âge réel inconnu"],["Affiliations","sportif"],["Nationalité d’origine","japonaise"],["Nature réelle","orque (thulkar)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Mash est une guerrière de la horde divine, elle se drogue, boit de l’alcool et s’empoisonne régulièrement pour dégrader son corps et être « au niveau humain ». Même presque morte, elle gagne généralement tous ses combats, même si elle est souvent en difficulté tant elle s’impose de graves handicaps. Elle a une mauvaise image dans la Réalité, on la pense simplement dopée ou addict, mais sa constitution monstrueuse de Thulkar lui pose un grave souci : elle mithridatise incroyablement mieux que les humains, l’alcool n’a presque plus aucun effet par exemple. Heureusement, en 2035, des drogues plus ravageuses existent et des soins pour que ça ne soit pas définitif également. Ashorn la respecte énormément, car plutôt que s’ennuyer à son vrai haut niveau, elle se diminue sans cesse pour que le moindre adversaire même méprisable soit un défi digne d’intérêt."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-mathilda-trash-34","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mathilda Trash","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Mathilda Trash","real_name_source":"Mathilda Trash","nom_verite":"Mjorg’trosh","nom_verite_source":"Mjorg’trosh","race":"Orques (thulkar)","age":"38 ans","origine":"américaine","statut":"","affiliations":"corporatiste - Tuatha","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[27],"source_occurrences":1,"source_order":2,"identity_keys":["Mathilda Trash","Mjorg’trosh","Horde de la rose : Mjorg’Trosh"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde de la rose : Mjorg’Trosh Nom de la Réalité : Mathilda Trash Nom de la Vérité : Mjorg’trosh Age : « 38 ans « - ?? ans Affiliations : corporatiste - Tuatha Nationalité d’origine : américaine Ethnie réelle : Orques (thulkar) Titre de la horde : Maitre de horde Née Martin Todd, Mathilda a toujours rêvé de devenir une grande actrice d’Hollywood, mais avec son physique excessivement masculin et naturellement musclée, elle abandonna jusqu’à ce qu’on ne lui présente à Angel’s Fall, une jeune actrice, nommée Siobhain, qui, partageant le même rêve, l’encouragea et bien que plus jeune, devint son modèle. Mathilda se refusa à la moindre opération, voulant briller par sa beauté naturelle et son talent. Un choix qui, hélas ne porta pas beaucoup ses fruits. Mjorg reste un chef orc redoutable, bien qu’il pousse sa horde à refuser les métiers de force où l’intelligence et l’adresse ne sont pas de rigueur, en effet, il estime qu’un Thulkar n’a pas à rougir d’un humain, un elfe ou un nain dans AUCUN domaine. Eduqué par une elfe ancienne, il a très mal interprété la notion de « beauté elfique » ou, du moins, en est plus une parodie qu’autre chose parfois. Bien qu’il joue un rôle dans la Réalité, c’est un hédoniste de nature, il aime le luxe, les arts, la fête et la bonne nourriture. Les daemons de Lilith le côtoient et l’ont progressivement converti, mais Urielle est une de ses amies. Ce qu’il vaut mieux garder en tête, c’est que la horde de la rose n’est pas pacifiste, Si on énerve Mjorg, il est possiblement aussi redoutable combattant que Kian ou Mash de la horde divine."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Mathilda Trash"],["Âge apparent","38 ans"],["Nationalité déclarée","américaine"]]},{"type":"p","text":"Née Martin Todd, Mathilda a toujours rêvé de devenir une grande actrice d’Hollywood, mais avec son physique excessivement masculin et naturellement musclée, elle abandonna jusqu’à ce qu’on ne lui présente à Angel’s Fall, une jeune actrice, nommée Siobhain, qui, partageant le même rêve, l’encouragea et bien que plus jeune, devint son modèle. Mathilda se refusa à la moindre opération, voulant briller par sa beauté naturelle et son talent. Un choix qui, hélas ne porta pas beaucoup ses fruits."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde de la rose : Mjorg’Trosh"],["Nom de la Réalité","Mathilda Trash"],["Nom de la Vérité","Mjorg’trosh"],["Âge complet","38 ans en apparence ; âge réel inconnu"],["Affiliations","corporatiste - Tuatha"],["Nationalité d’origine","américaine"],["Nature réelle","Orques (thulkar)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Mjorg reste un chef orc redoutable, bien qu’il pousse sa horde à refuser les métiers de force où l’intelligence et l’adresse ne sont pas de rigueur, en effet, il estime qu’un Thulkar n’a pas à rougir d’un humain, un elfe ou un nain dans AUCUN domaine. Eduqué par une elfe ancienne, il a très mal interprété la notion de « beauté elfique » ou, du moins, en est plus une parodie qu’autre chose parfois. Bien qu’il joue un rôle dans la Réalité, c’est un hédoniste de nature, il aime le luxe, les arts, la fête et la bonne nourriture. Les daemons de Lilith le côtoient et l’ont progressivement converti, mais Urielle est une de ses amies. Ce qu’il vaut mieux garder en tête, c’est que la horde de la rose n’est pas pacifiste, Si on énerve Mjorg, il est possiblement aussi redoutable combattant que Kian ou Mash de la horde divine."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-grim-grigoria-ravinsky-35","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"« Grim », Grigoria Ravinsky","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"« Grim », Grigoria Ravinsky","real_name_source":"« Grim », Grigoria RAVINSKY","nom_verite":"Greem’Sha","nom_verite_source":"Greem’Sha","race":"Orques (thulkar)","age":"48 ans","origine":"Ukrainienne","statut":"","affiliations":"pègre (bratva)","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[28],"source_occurrences":1,"source_order":2,"identity_keys":["« Grim », Grigoria RAVINSKY","Grim","Greem’Sha","Horde Abyssale : Greem’Sha","« Grim », Grigoria Ravinsky"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde Abyssale : Greem’Sha Nom de la Réalité : « Grim », Grigoria RAVINSKY Nom de la Vérité : Greem’Sha Age : « 48 ans » - ??? Affiliations : pègre (bratva) Nationalité d’origine : Ukrainienne Ethnie réelle : Orques (thulkar) Titre de la horde : Maitre de horde Grigoria RAVINSKY était une subordonnée de Drasko VLADIC dans l’escadron fantôme qu’il menait, des pro-russes qui se rallièrent aux troupes de l’Arkhangel durant la guerre de 22-28. Tout comme Drasko, c’était une dure à cuir et une psychopathe en puissance étant donné ce qu’elle avait vécu jusque-là. Fille de Thul, un fléau majeur, c’est une disciple d’Ashorn. Chez les Thulkar, elle n’est pas considérée comme un Fléau, bien qu’elle en soit la fille, mais comme une grande figure vu le nombre de guerres et de batailles auxquelles elle a participé. N’importe quel orc peut avoir un entretien avec elle, mais le prix est un combat et il peut avoir pour conséquence de graves blessures ou la mort. Elle prive les perdants de toutes leurs armes et de leurs habits, mais elle rend souvent le service demandé malgré toute l’humiliation infligée."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","« Grim », Grigoria Ravinsky"],["Âge apparent","48 ans"],["Nationalité déclarée","Ukrainienne"]]},{"type":"p","text":"Grigoria RAVINSKY était une subordonnée de Drasko VLADIC dans l’escadron fantôme qu’il menait, des pro-russes qui se rallièrent aux troupes de l’Arkhangel durant la guerre de 22-28. Tout comme Drasko, c’était une dure à cuir et une psychopathe en puissance étant donné ce qu’elle avait vécu jusque-là."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde Abyssale : Greem’Sha"],["Nom de la Réalité","« Grim », Grigoria Ravinsky"],["Nom de la Vérité","Greem’Sha"],["Âge complet","48 ans en apparence ; âge réel inconnu"],["Affiliations","pègre (bratva)"],["Nationalité d’origine","Ukrainienne"],["Nature réelle","Orques (thulkar)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Fille de Thul, un fléau majeur, c’est une disciple d’Ashorn. Chez les Thulkar, elle n’est pas considérée comme un Fléau, bien qu’elle en soit la fille, mais comme une grande figure vu le nombre de guerres et de batailles auxquelles elle a participé. N’importe quel orc peut avoir un entretien avec elle, mais le prix est un combat et il peut avoir pour conséquence de graves blessures ou la mort. Elle prive les perdants de toutes leurs armes et de leurs habits, mais elle rend souvent le service demandé malgré toute l’humiliation infligée."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-kristian-morales-36","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kristian Morales","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kristian Morales","real_name_source":"Kristian Morales","nom_verite":"Kran’Rag","nom_verite_source":"Kran’Rag","race":"Orques (thulkar)","age":"27 ans","origine":"américaine","statut":"","affiliations":"crawlers (neopunks)","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[29],"source_occurrences":1,"source_order":1,"identity_keys":["Kristian Morales","Kran’Rag","Horde fantôme: Kran’Rag"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde fantôme: Kran’Rag Nom de la Réalité : Kristian Morales Nom de la Vérité : Kran’Rag Age : « 27 ans » Affiliations : crawlers (neopunks) Nationalité d’origine : américaine Ethnie réelle : Orques (thulkar) Titre de la horde : Maitre de horde Kristian Morales est le batteur de the Void. C’est un orc également même si ce neopunk se fout assez du combat et de la culture martiale qu’on peut retrouver chez d’autres membres de son espèce. Il appartient à la horde fantôme, laquelle a pour philosophie d’être la plus discrète possible, la mieux intégrée dans la Réalité et la moins identifiable, elle est donc relativement lointaine de la horde divine, très militaire ou de la horde sacrée, très influente dans les corporations et la politique. Kran’Rag est le seul chef vaguement connu de cette horde, il n’a aucun lien avéré avec le syndicat de Jade, tout le réseau de la horde est donc plutôt fermé, il n’en est pas moins efficace puisqu’il repose sur les réseaux de neopunks et d’insurgés."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Kristian Morales"],["Âge apparent","27 ans"],["Nationalité déclarée","américaine"]]},{"type":"p","text":"Kristian Morales est le batteur de the Void."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde fantôme: Kran’Rag"],["Nom de la Réalité","Kristian Morales"],["Nom de la Vérité","Kran’Rag"],["Âge complet","27 ans en apparence ; âge réel inconnu"],["Affiliations","crawlers (neopunks)"],["Nationalité d’origine","américaine"],["Nature réelle","Orques (thulkar)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"C’est un orc également même si ce neopunk se fout assez du combat et de la culture martiale qu’on peut retrouver chez d’autres membres de son espèce. Il appartient à la horde fantôme, laquelle a pour philosophie d’être la plus discrète possible, la mieux intégrée dans la Réalité et la moins identifiable, elle est donc relativement lointaine de la horde divine, très militaire ou de la horde sacrée, très influente dans les corporations et la politique. Kran’Rag est le seul chef vaguement connu de cette horde, il n’a aucun lien avéré avec le syndicat de Jade, tout le réseau de la horde est donc plutôt fermé, il n’en est pas moins efficace puisqu’il repose sur les réseaux de neopunks et d’insurgés."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-madeleyn-sheperd-37","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Madeleyn Sheperd","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Madeleyn Sheperd","real_name_source":"Madeleyn Sheperd","nom_verite":"Morg’Shey","nom_verite_source":"Morg’Shey","race":"Orques (thulkar)","age":"32 ans","origine":"Américaine","statut":"","affiliations":"Crawlers : Hookers","source_group":"Hordes orques","source_groups":["Hordes orques"],"source_pages":[29],"source_occurrences":1,"source_order":2,"identity_keys":["Madeleyn Sheperd","Morg’Shey","Horde maudite : Morg’Shey"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Horde maudite : Morg’Shey Nom de la Réalité : Madeleyn Sheperd Nom de la Vérité : Morg’Shey Age : « 32 ans « - ?? ans Affiliations : Crawlers : Hookers Nationalité d’origine : Américaine Ethnie réelle : Orques (thulkar) Titre de la horde : Maitre de horde « Mad Shey » est une sans abris des quartiers abandonnés, elle a un « logifate toxique », pas seulement négatif, il corrompt celui des citoyens la côtoyant. Très pauvre, elle maraude dans les ruelles en gérant son réseau de clochards crasseux. Elle-même est prostituée, c’est la seule assez belle de sa bande au demeurant, les autres étant au mieux vaguement laids, au pire ils sont d’une laideur et d’une difformité rare. Elle a des méthodes très agressives, se servant de son physique athlétique pour coincer ses clients les plus réticents, souvent, le but est de faire un chantage au logifate ultérieurement. C’est la chef de la Horde maudite, une communauté ayant trop longtemps vécu sur elle-même, un des gros défauts des exilés les plus éloignés de grande communautés c’est qu’assez vite ils disparaissent ou finissent consanguin, c’est le cas de la horde maudite. 80% d’entre eux sont laids, malades et malformés, une poignée sont difforme mais avec un physique hors norme, deux fois plus grands qu’un thulkar de la Terre. Morg est l’une des très rares à peu près normale, ce n’est pas que par plaisir qu’elle se prostitue de fait. Elle cherche des petites hordes à intégrer sans cesse depuis qu’elle est arrivée en Californie. La consanguinité de sa horde n’offre aucun avantage hormis que ses orques détestent leur corps et s’augmente sans avoir l’impression de perdre quelque chose, ils tolèrent bien les opérations."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Madeleyn Sheperd"],["Âge apparent","32 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"« Mad Shey » est une sans abris des quartiers abandonnés, elle a un « logifate toxique », pas seulement négatif, il corrompt celui des citoyens la côtoyant. Très pauvre, elle maraude dans les ruelles en gérant son réseau de clochards crasseux. Elle-même est prostituée, c’est la seule assez belle de sa bande au demeurant, les autres étant au mieux vaguement laids, au pire ils sont d’une laideur et d’une difformité rare. Elle a des méthodes très agressives, se servant de son physique athlétique pour coincer ses clients les plus réticents, souvent, le but est de faire un chantage au logifate ultérieurement."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Horde maudite : Morg’Shey"],["Nom de la Réalité","Madeleyn Sheperd"],["Nom de la Vérité","Morg’Shey"],["Âge complet","32 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : Hookers"],["Nationalité d’origine","Américaine"],["Nature réelle","Orques (thulkar)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"C’est la chef de la Horde maudite, une communauté ayant trop longtemps vécu sur elle-même, un des gros défauts des exilés les plus éloignés de grande communautés c’est qu’assez vite ils disparaissent ou finissent consanguin, c’est le cas de la horde maudite. 80% d’entre eux sont laids, malades et malformés, une poignée sont difforme mais avec un physique hors norme, deux fois plus grands qu’un thulkar de la Terre. Morg est l’une des très rares à peu près normale, ce n’est pas que par plaisir qu’elle se prostitue de fait. Elle cherche des petites hordes à intégrer sans cesse depuis qu’elle est arrivée en Californie. La consanguinité de sa horde n’offre aucun avantage hormis que ses orques détestent leur corps et s’augmente sans avoir l’impression de perdre quelque chose, ils tolèrent bien les opérations."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-russell-vinderbeck-38","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Russell Vinderbeck","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Enfants de Nidavellir","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Russell Vinderbeck","real_name_source":"Russell VINDERBECK","nom_verite":"Russell Vinderbeck","nom_verite_source":"Russell VINDERBECK","race":"nains (whurtens)","age":"46 ans","origine":"Belge","statut":"","affiliations":"Corporatiste : yellowfood","source_group":"Enfants de Nidavellir","source_groups":["Enfants de Nidavellir"],"source_pages":[31],"source_occurrences":1,"source_order":1,"identity_keys":["Russell VINDERBECK","faction Elegarin (Nibelungen) : Russell Vinderbeck","Nibelungen","Russell Vinderbeck"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"faction Elegarin (Nibelungen) : Russell Vinderbeck Nom de la Réalité : Russell VINDERBECK Nom de la Vérité : Russell VINDERBECK Age : « 46 ans » - ??? ans Affiliations : Corporatiste : yellowfood Nationalité d’origine : Belge Ethnie réelle : nains (whurtens) Titre dans la faction : Maitre Russell Vinderberk est un corporatiste de Yellowfood, ancien ami de Roberrick et mentor de l’ancien mercenaire, c’est lui qui le finança à ses débuts, comptant sur une branche plus classique et traditionnelle à Yellowfood. Trahi par Roberrick Reimer, qui créa sa propre corporation dwarfood, il s’est retrouvé en mauvaise posture dans sa corporation (yellowfood). Malgré un air perpétuellement jovial, Russell est un corporatiste assez impitoyable et trompeur, il investit beaucoup sans trop regarder à la dépense, dans des projets, des missions de crawlers ou des infrastructures puis, il exige de lourds retours et intérêts, il n’est jamais perdant. Ancien siège de la faction Nibelungen au « conseil des Anciens », il n’a pas été trahi par son ami Roberrick que dans la Réalité, il a aussi été destitué. Ulracapitaliste, il avait peu d’amitiés dans le conseil, voulant faire des Silcenters des plaques tournantes d’un marché de la Vérité, traitant parfois avec des Mages, ce qui passait mal. Sa faction, les « Elegarins » prône une plus grande mixité entre exilés, voulant intégrer les gobelins et utiliser la magie pour abolir les races fantastiques en permettant leur croisement, ils sont, selon la faction, trop peu nombreux pour avoir un avenir sans se métisser durablement.","protect_truth_metadata":true},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Russell Vinderbeck"],["Âge apparent","46 ans"],["Nationalité déclarée","Belge"]]},{"type":"p","text":"Russell Vinderberk est un corporatiste de Yellowfood, ancien ami de Roberrick et mentor de l’ancien mercenaire, c’est lui qui le finança à ses débuts, comptant sur une branche plus classique et traditionnelle à Yellowfood. Trahi par Roberrick Reimer, qui créa sa propre corporation dwarfood, il s’est retrouvé en mauvaise posture dans sa corporation (yellowfood). Malgré un air perpétuellement jovial, Russell est un corporatiste assez impitoyable et trompeur, il investit beaucoup sans trop regarder à la dépense, dans des projets, des missions de crawlers ou des infrastructures puis, il exige de lourds retours et intérêts, il n’est jamais perdant."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","faction Elegarin (Nibelungen) : Russell Vinderbeck"],["Nom de la Réalité","Russell Vinderbeck"],["Nom de la Vérité","Russell Vinderbeck"],["Âge complet","46 ans en apparence ; âge réel inconnu"],["Affiliations","Corporatiste : yellowfood"],["Nationalité d’origine","Belge"],["Nature réelle","nains (whurtens)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Ancien siège de la faction Nibelungen au « conseil des Anciens », il n’a pas été trahi par son ami Roberrick que dans la Réalité, il a aussi été destitué. Ulracapitaliste, il avait peu d’amitiés dans le conseil, voulant faire des Silcenters des plaques tournantes d’un marché de la Vérité, traitant parfois avec des Mages, ce qui passait mal. Sa faction, les « Elegarins » prône une plus grande mixité entre exilés, voulant intégrer les gobelins et utiliser la magie pour abolir les races fantastiques en permettant leur croisement, ils sont, selon la faction, trop peu nombreux pour avoir un avenir sans se métisser durablement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-helmi-liikanen-39","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Helmi Liikanen","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Enfants de Nidavellir","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Helmi Liikanen","real_name_source":"Helmi LIIKANEN","nom_verite":"Helmi Dar’Kanen","nom_verite_source":"Helmi DAR’KANEN","race":"nains (whurtens)","age":"45 ans","origine":"Finlandaise","statut":"","affiliations":"Corporatiste : Raven /Crawlers (cyppers)","source_group":"Enfants de Nidavellir","source_groups":["Enfants de Nidavellir"],"source_pages":[31],"source_occurrences":1,"source_order":2,"identity_keys":["Helmi LIIKANEN","Helmi DAR’KANEN","faction traditions (Nibelungen) : Helmi Liikanen","Nibelungen","Helmi Liikanen","Helmi Dar’Kanen"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"faction traditions (Nibelungen) : Helmi Liikanen Nom de la Réalité : Helmi LIIKANEN Nom de la Vérité : Helmi DAR’KANEN Age : « 45 ans » - ??? ans Affiliations : Corporatiste : Raven /Crawlers (cyppers) Nationalité d’origine : Finlandaise Ethnie réelle : nains (whurtens) Titre dans la faction : Maitre Helmi est un ingénieur de la Raven Corporation. Elle a un style neopunk et une personnalité très indépendante, c’est une femme qui, pourtant a visiblement toute la confiance des hauts cadres puisqu’elle est dans toutes les branches, sur de nombreux projets. Pourtant, elle vend aussi sous le manteau du matériel de la Raven en tant que Crawler, du matériel qu’elle modifie elle-même. C’est une ancienne forgeronne née sur Aèr, elle vénérait déjà Morrighan et était une forgeronne à son service, elle est légendaire et travaille nécessairement à la Raven pour sa déesse. Elle a le droit de vendre illégalement des prototypes, pour tester des choses. Bien qu’elle soit une vraie corporatiste, elle est parfois engagée de force en tant que Crawlers par ses clients. Elle est assez jalouse du génie de Leslie Wright. Elle dirige les traditionnalistes chez les Whurtens, ceux qui se refusent à renoncer aux anciens dieux d’Aèr, aux clans et aux runes notamment, aux anciennes langues et d’autres savoirs."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Helmi Liikanen"],["Âge apparent","45 ans"],["Nationalité déclarée","Finlandaise"]]},{"type":"p","text":"Helmi est un ingénieur de la Raven Corporation. Elle a un style neopunk et une personnalité très indépendante, c’est une femme qui, pourtant a visiblement toute la confiance des hauts cadres puisqu’elle est dans toutes les branches, sur de nombreux projets. Pourtant, elle vend aussi sous le manteau du matériel de la Raven en tant que Crawler, du matériel qu’elle modifie elle-même."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","faction traditions (Nibelungen) : Helmi Liikanen"],["Nom de la Réalité","Helmi Liikanen"],["Nom de la Vérité","Helmi Dar’Kanen"],["Âge complet","45 ans en apparence ; âge réel inconnu"],["Affiliations","Corporatiste : Raven /Crawlers (cyppers)"],["Nationalité d’origine","Finlandaise"],["Nature réelle","nains (whurtens)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"C’est une ancienne forgeronne née sur Aèr, elle vénérait déjà Morrighan et était une forgeronne à son service, elle est légendaire et travaille nécessairement à la Raven pour sa déesse. Elle a le droit de vendre illégalement des prototypes, pour tester des choses. Bien qu’elle soit une vraie corporatiste, elle est parfois engagée de force en tant que Crawlers par ses clients. Elle est assez jalouse du génie de Leslie Wright. Elle dirige les traditionnalistes chez les Whurtens, ceux qui se refusent à renoncer aux anciens dieux d’Aèr, aux clans et aux runes notamment, aux anciennes langues et d’autres savoirs."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-bob-40","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Bob","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Enfants de Nidavellir","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Bob","real_name_source":"Bob","nom_verite":"Motsognir Vonrim","nom_verite_source":"Motsognir Vonrim","race":"nains (whurtens)","age":"âge apparent inconnu","origine":"aucune (supposément canadienne)","statut":"","affiliations":"aucune (sans-abris)","source_group":"Enfants de Nidavellir","source_groups":["Enfants de Nidavellir"],"source_pages":[32],"source_occurrences":1,"source_order":1,"identity_keys":["Bob","Motsognir Vonrim","faction Nidavellin (Duergars) : : Motsognir","Duergars"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"faction Nidavellin (Duergars) : : Motsognir Nom de la Réalité : Bob Nom de la Vérité : Motsognir Vonrim Age : « ??? » Affiliations : aucune (sans-abris) Nationalité d’origine : aucune (supposément canadienne) Ethnie réelle : nains (whurtens) Titre dans la faction : Maitre Bob est un clochard qu’on a repéré à Los Angeles, aigri et avec un accent supposément canadien, on ne sait trop rien de lui. Motsognir est LE nain le plus dangereux de la Terre. Mis de coté les dieux et Anahita, il est dans les 25 entités les plus puissantes en maitrise de la magie, Mages et Dives compris. Il s’est gravé une forme évoquant un Mageius sur le front et son âme comme son corps sont aussi proche du Whurten que de l’Ombre. Il a chassé les gobelins et les gorgones des profondeurs. Il rejette la surface, le conseil des Anciens et les exilés. Il ne vénère pas les Fléaux néanmoins, au contraire, il lutte contre sa propre fille, corrompue par V’aagor. Il ne vénère que la Magie elle-même, il lutte contre le fanatisme religieux chez les Duergars, sa faction, sa seule dévotion va à Anahita. Des rumeurs disent que c’est parce qu’il aurait dévoré des souvenir d’Ymir. Il n’est ni un dieu ni un mage mais il reste une « source magique », un être capable de raffiner la magie et la donner à ses fidèles. Il cherche à traquer le « premier deimon », une entité similaire à Ymir chez les Dives ou l’Ancienne chez les Kochtchei."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Bob"],["Âge apparent","âge apparent inconnu"],["Nationalité déclarée","aucune (supposément canadienne)"]]},{"type":"p","text":"Bob est un clochard qu’on a repéré à Los Angeles, aigri et avec un accent supposément canadien, on ne sait trop rien de lui."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","faction Nidavellin (Duergars) : : Motsognir"],["Nom de la Réalité","Bob"],["Nom de la Vérité","Motsognir Vonrim"],["Âge complet","Âge inconnu"],["Affiliations","aucune (sans-abris)"],["Nationalité d’origine","aucune (supposément canadienne)"],["Nature réelle","nains (whurtens)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Motsognir est LE nain le plus dangereux de la Terre. Mis de coté les dieux et Anahita, il est dans les 25 entités les plus puissantes en maitrise de la magie, Mages et Dives compris. Il s’est gravé une forme évoquant un Mageius sur le front et son âme comme son corps sont aussi proche du Whurten que de l’Ombre. Il a chassé les gobelins et les gorgones des profondeurs. Il rejette la surface, le conseil des Anciens et les exilés. Il ne vénère pas les Fléaux néanmoins, au contraire, il lutte contre sa propre fille, corrompue par V’aagor. Il ne vénère que la Magie elle-même, il lutte contre le fanatisme religieux chez les Duergars, sa faction, sa seule dévotion va à Anahita. Des rumeurs disent que c’est parce qu’il aurait dévoré des souvenir d’Ymir. Il n’est ni un dieu ni un mage mais il reste une « source magique », un être capable de raffiner la magie et la donner à ses fidèles. Il cherche à traquer le « premier deimon », une entité similaire à Ymir chez les Dives ou l’Ancienne chez les Kochtchei."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-fredegonda-vonrim-41","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Fredegonda Vonrim","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Enfants de Nidavellir","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"Aucun","nom_verite":"Fredegonda Vonrim","nom_verite_source":"Fredegonda VONRIM","race":"nains (whurtens)/ Ombre (deimons)","age":"âge apparent inconnu ; âge réel inconnu","origine":"aucune (supposément canadienne)","statut":"","affiliations":"Abominations (Duergars)","source_group":"Enfants de Nidavellir","source_groups":["Enfants de Nidavellir"],"source_pages":[32],"source_occurrences":1,"source_order":2,"identity_keys":["Fredegonda VONRIM","Faction Vagorrin (Duergars): Fredegonda","Duergars","Fredegonda Vonrim"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Faction Vagorrin (Duergars): Fredegonda Nom de la Réalité : Aucun Nom de la Vérité : Fredegonda VONRIM Age : « ??? » - ???? ans Affiliations : Abominations (Duergars) Nationalité d’origine : aucune (supposément canadienne) Ethnie réelle : nains (whurtens)/ Ombre (deimons) Titre dans la faction : Maitre Fredegonda est la fille de Motsognir et d’une Ombre, un deimon que Motsognior façonna pour que l’ombre n’ait une apparence féminine. Comme beaucoup de Duergars, elle est donc en partie deimone. Hélas, son corps se désagrège, plus deimone que Whurtenne, lui valant le nom de « Putride ». Ce n’est pas qu’ill pourri, mais qu’il n’a pas de cohérence, c’est un amas de viande et de poussières cherchant à se désagréger. Elle parait sale et souffrait infiniment et constamment avant de devenir le réceptacle d’une partie de V’aagor. Alliée à L’ombre-Pape, elle ne connait pas les Nibelungen et si elle est naturellement leur ennemie, elle envie plus la surface qu’elle ne la déteste. Elle veut libérer V’Aagor pour que les Duergars ne puissent vivre à la surface sans l’immonde soleil qui les disperse en partie. Elle est l’ennemie de son père et sort parfois la nuit, à la surface où elle s’émerveille de la beauté des créatures humaines, hypnotisées par les publicités de la Tuatha par exemple, enviant la beauté des gens de la surface, elle qui se sent sale, laide et éphémère. Un de ses lus immondes pouvoirs est qu’on ne peut la tuer, car si son corps se disperse, la portion de V’aagor en elle va dans le corps de celui la tuant, il corrompt alors plus vite l’assassin que Fredegonda ne meurt, jusque-là, aucun assaillant n’est allé jusqu’au bout."},"sections":[{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Faction Vagorrin (Duergars): Fredegonda"],["Nom de la Réalité","Aucune couverture humaine renseignée"],["Nom de la Vérité","Fredegonda Vonrim"],["Âge complet","Âge inconnu"],["Affiliations","Abominations (Duergars)"],["Nationalité d’origine","aucune (supposément canadienne)"],["Nature réelle","nains (whurtens)/ Ombre (deimons)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Fredegonda est la fille de Motsognir et d’une Ombre, un deimon que Motsognior façonna pour que l’ombre n’ait une apparence féminine. Comme beaucoup de Duergars, elle est donc en partie deimone. Hélas, son corps se désagrège, plus deimone que Whurtenne, lui valant le nom de « Putride ». Ce n’est pas qu’ill pourri, mais qu’il n’a pas de cohérence, c’est un amas de viande et de poussières cherchant à se désagréger. Elle parait sale et souffrait infiniment et constamment avant de devenir le réceptacle d’une partie de V’aagor. Alliée à L’ombre-Pape, elle ne connait pas les Nibelungen et si elle est naturellement leur ennemie, elle envie plus la surface qu’elle ne la déteste. Elle veut libérer V’Aagor pour que les Duergars ne puissent vivre à la surface sans l’immonde soleil qui les disperse en partie. Elle est l’ennemie de son père et sort parfois la nuit, à la surface où elle s’émerveille de la beauté des créatures humaines, hypnotisées par les publicités de la Tuatha par exemple, enviant la beauté des gens de la surface, elle qui se sent sale, laide et éphémère. Un de ses lus immondes pouvoirs est qu’on ne peut la tuer, car si son corps se disperse, la portion de V’aagor en elle va dans le corps de celui la tuant, il corrompt alors plus vite l’assassin que Fredegonda ne meurt, jusque-là, aucun assaillant n’est allé jusqu’au bout."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-grands-exiles-atreesha-johnson-42","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Atreesha Johnson","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Ligue des Quatre Empereurs","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Atreesha Johnson","real_name_source":"Atreesha JOHNSON","nom_verite":"Atreesha","nom_verite_source":"Atreesha","race":"Gobelins","age":"49 ans","origine":"américaine","statut":"","affiliations":"Corporatiste : Tuatha","source_group":"Ligue des Quatre Empereurs","source_groups":["Ligue des Quatre Empereurs"],"source_pages":[34],"source_occurrences":1,"source_order":1,"identity_keys":["Atreesha JOHNSON","Atreesha","siège impérial : Atreesha","Atreesha Johnson"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"siège impérial : Atreesha Nom de la Réalité : Atreesha JOHNSON Nom de la Vérité : Atreesha Age : «49 ans » - ???? ans Affiliations : Corporatiste : Tuatha Nationalité d’origine : américaine Ethnie réelle : Gobelins Titre dans la faction : Impératrice Atreesha est une actrice afro-américaine de presque 50 ans qui ne fait absolument pas son âge. Loin d’être une des plus grandes Stars d’Hollywood, elle est cantonnée aux seconds rôles mais elle jouit d’une réputation de rigueur et de professionnalisme qui se conjugue bien avec son énergie inépuisable, enchainant le plus de projets que bien des artistes. Elle a toutefois un tempérament explosif, elle ne supporte pas les pseudo-artistes retardataires et déglingués et a tendance à les faire virer comme elle peut, parfois par un harcèlement agressif. Plus ancienne gobeline sur Terre, elle est l’incontournable impératrice Atreesha. Officiellement née sur Terre et capturée, elle est en vérité née on ne sait où, peut être Aèr ou peut être sur Terre, régnant sur un territoire en deux parties, sur deux mondes. En étant chassée des souterrains par Motsognir, après la guerre de la Magie, elle a tout fait pour s’intégrer au Conseil des Anciens, mais sans réussite, ses propres vassaux lui plantant ses projets par pure ambition égoïste. Lassée et profondément vexée de ne pas siégée, d’avoir été trahie et de voir ses efforts permettre de constituer le Syndicat de Jade, elle ne gère que la Ligue, avec un certain détachement. Elle est l’amie de Sil’Elaith, d’Ashorn et d’Obéron."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Atreesha Johnson"],["Âge apparent","49 ans"],["Nationalité déclarée","américaine"]]},{"type":"p","text":"Atreesha est une actrice afro-américaine de presque 50 ans qui ne fait absolument pas son âge. Loin d’être une des plus grandes Stars d’Hollywood, elle est cantonnée aux seconds rôles mais elle jouit d’une réputation de rigueur et de professionnalisme qui se conjugue bien avec son énergie inépuisable, enchainant le plus de projets que bien des artistes. Elle a toutefois un tempérament explosif, elle ne supporte pas les pseudo-artistes retardataires et déglingués et a tendance à les faire virer comme elle peut, parfois par un harcèlement agressif."}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","siège impérial : Atreesha"],["Nom de la Réalité","Atreesha Johnson"],["Nom de la Vérité","Atreesha"],["Âge complet","49 ans en apparence ; âge réel inconnu"],["Affiliations","Corporatiste : Tuatha"],["Nationalité d’origine","américaine"],["Nature réelle","Gobelins"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Plus ancienne gobeline sur Terre, elle est l’incontournable impératrice Atreesha. Officiellement née sur Terre et capturée, elle est en vérité née on ne sait où, peut être Aèr ou peut être sur Terre, régnant sur un territoire en deux parties, sur deux mondes. En étant chassée des souterrains par Motsognir, après la guerre de la Magie, elle a tout fait pour s’intégrer au Conseil des Anciens, mais sans réussite, ses propres vassaux lui plantant ses projets par pure ambition égoïste. Lassée et profondément vexée de ne pas siégée, d’avoir été trahie et de voir ses efforts permettre de constituer le Syndicat de Jade, elle ne gère que la Ligue, avec un certain détachement. Elle est l’amie de Sil’Elaith, d’Ashorn et d’Obéron."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
